{
  "name": "UxBus 串口协议通信组件",
  "name_en": "UxBus Serial Protocol Communication Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于通过串口封装、发送、接收并校验 UxBus/Modbus 风格的协议报文。它主要服务于实验系统中的设备通信流程，例如设置协议标识、检查协议头、处理私有协议以及收发请求与响应数据。",
  "description_en": "This is a non-physical software communication component used to package, send, receive, and validate UxBus/Modbus-style protocol frames over serial links. It supports lab-system device communications such as setting protocol identifiers, checking protocol headers, handling private protocol formats, and transferring request/response data.",
  "tag_hints": [
    "serial communication",
    "Modbus protocol",
    "protocol framing",
    "message validation",
    "device communication helper",
    "error and warning status",
    "xArm ecosystem"
  ],
  "actions": [
    {
      "action_name": "auto-has_err_warn",
      "description": "获取/设置错误与警告状态",
      "description_en": "get/set error and warning status"
    },
    {
      "action_name": "auto-set_protocol_identifier",
      "description": "设置协议标识符",
      "description_en": "set protocol identifier"
    },
    {
      "action_name": "auto-check_protocol_header",
      "description": "检查协议头是否符合给定的事务标识、协议标识和单元标识，用于验证接收报文。",
      "description_en": "Check whether a protocol header matches the expected transaction ID, protocol ID, and unit ID to validate a received message."
    },
    {
      "action_name": "auto-check_private_protocol",
      "description": "检查数据是否符合私有协议格式，用于识别和验证专用报文。",
      "description_en": "Check whether data matches the private protocol format for identifying and validating proprietary messages."
    },
    {
      "action_name": "auto-send_modbus_request",
      "description": "发送 Modbus 请求报文，包括寄存器地址、发送数据和协议相关参数。",
      "description_en": "Send a Modbus request frame including register address, payload data, and protocol-related parameters."
    },
    {
      "action_name": "auto-recv_modbus_response",
      "description": "接收 Modbus 响应报文，并按功能码、事务标识、长度和超时条件进行处理。",
      "description_en": "Receive a Modbus response frame and process it according to function code, transaction ID, expected length, and timeout."
    },
    {
      "action_name": "auto-get_protocol_identifier",
      "description": "获取协议标识符",
      "description_en": "get protocol identifier"
    }
  ]
}

